<script lang="ts">
 import Icon from '../components/Icon.svelte';
 import NodeSpeedtest from '../components/NodeSpeedtest.svelte';
 import TunnelManager from '../components/TunnelManager.svelte';
 let tunnelOpen=$state(false);
 import {countryCode} from '../server-display';
 import {nodeRelay} from '../relay-address';
 import {nodeProtocol,nodeAddress,renamedNode} from '../node-workbench';
 import {inboundManagerURL} from '../server-inbounds';
 import {onDestroy} from 'svelte';
 import type {Row} from '../data';
 import {api,demo,saveRow,getRow,refreshState,runAction,copy,toast,errorMessage} from '../store.svelte';
 import Modal from '../components/Modal.svelte';
 import Badge from '../components/Badge.svelte';
 import CountryBadge from '../components/CountryBadge.svelte';
 import ManagedProtocolFields from '../components/ManagedProtocolFields.svelte';
 import {withManagedFields,managedInboundError,prepareManagedInbound} from '../managed-protocols';
 import {withRealityFields} from '../reality';
 import {routingURL} from '../routing';
 import {createNodeLatencyTests} from '../node-latency-state.svelte';
 import {canTestNode} from '../resource-permissions';

 let search=$state(''),source=$state(''),server=$state(''),tag=$state(''),status=$state(''),protocol=$state(''),sortMode=$state(false);
 let selected=$state<string[]>([]),busy=$state(false),error=$state(''),taskIDs=$state<string[]>([]);
 let createOpen=$state(false),step=$state(1),keyBusy=$state(false),form=$state<Row>({id:''});
 let importText=$state(''),preview=$state<any>(null),importTags=$state(''),imported=$state(false);
 let editOpen=$state(false),editRow=$state<Row|null>(null),name=$state(''),tags=$state(''),region=$state(''),description=$state('');
 let deleteOpen=$state(false),bulkOpen=$state(false),bulkTags=$state('');
 let connectionIntent=$state('view'),connectionOpen=$state(false),connectionNode=$state<Row|null>(null),subscriptions=$state<Row[]>([]),subscriptionID=$state(''),connection=$state<any>(null);
 let offset=$state(0),renameOpen=$state(false),renameMode=$state('name'),renamePrefix=$state(''),renameFind=$state(''),renameReplacement=$state(''),renameSuffix=$state(''),batchRows=$state<Row[]>([]),deleteTargets=$state<Row[]>([]);
 let syncOpen=$state(false),syncSelected=$state<string[]>([]),syncDone=$state<string[]>([]);
 let speedOpen=$state(false),speedSelection=$state<string[]>([]);
 const admin=$derived(demo.user?.role==='admin');
 const rows=$derived([...(demo.data.nodes??[])].sort((a,b)=>(a.sortOrder??0)-(b.sortOrder??0)||String(a.name).localeCompare(String(b.name))));
 const tagsOf=(row:Row):string[]=>Array.isArray(row.tags)?row.tags:String(row.tags??'').split(/[,，]+/).map(s=>s.trim()).filter(Boolean);
 const sources=$derived([...new Set(rows.map(r=>String(r.source??(r.managedInbound?'受管入站':'手动导入'))))]);
 const allTags=$derived([...new Set(rows.flatMap(tagsOf))]);
 const protocols=$derived([...new Set(rows.map(nodeProtocol))]);
 const filtered=$derived(rows.filter(r=>(!protocol||nodeProtocol(r)===protocol)&&(!search||[r.name,r.host,r.server,r.region,...tagsOf(r)].join(' ').toLowerCase().includes(search.toLowerCase()))&&(!source||String(r.source??(r.managedInbound?'受管入站':'手动导入'))===source)&&(!server||r.serverId===server)&&(!tag||tagsOf(r).includes(tag))&&(!status||r.status===status)));
 const visible=$derived(filtered.slice(offset,offset+20));
 const chosen=$derived(rows.filter(r=>selected.includes(r.id)));
 const tcpTargets=$derived((chosen.length?chosen:filtered).filter(row=>canTestNode(demo.user?.role,row)));
 const tests=createNodeLatencyTests({identity:()=>demo.user?.id??'',canTest:id=>rows.some(r=>r.id===id&&canTestNode(demo.user?.role,r)),read:(id,signal)=>api('/api/actions',{method:'POST',body:JSON.stringify({action:'node.health.check',targetId:id,collection:'nodes'}),signal})});
 $effect(()=>{tests.syncIdentity();});
 $effect(()=>{search;source;server;tag;status;protocol;offset=0;});
 $effect(()=>{if(offset>=filtered.length&&offset>0)offset=Math.max(0,Math.floor((filtered.length-1)/20)*20);});
 $effect(()=>{const ids=new Set(rows.map(row=>row.id));if(selected.some(id=>!ids.has(id)))selected=selected.filter(id=>ids.has(id));});
 onDestroy(()=>tests.clear());
 const renamed=$derived(batchRows.map(row=>({row,name:renameMode==='emoji'?flagName(row):renamedNode(String(row.name),renamePrefix,renameFind,renameReplacement,renameSuffix)})));
 function flagName(row:Row){const code=countryCode(row.region);return code?String.fromCodePoint(...[...code].map(c=>127397+c.charCodeAt(0)))+' '+String(row.name).replace(/^[\u{1F1E6}-\u{1F1FF}]{2}\s*/u,''):String(row.name);}
 function startRename(mode:string){batchRows=chosen.map(row=>({...row}));renameMode=mode;renamePrefix='';renameFind='';renameReplacement='';renameSuffix='';error='';renameOpen=true;}
 function startDelete(targets:Row[]){deleteTargets=targets.map(row=>({...row}));error='';deleteOpen=true;}
 function startSync(){syncSelected=[...new Set(chosen.map(row=>row.sourceId).filter(id=>(demo.data.sources??[]).some(source=>source.id===id)))];syncDone=[];error='';syncOpen=true;}
 async function syncSources(){await perform(async()=>{const failures:string[]=[];for(const id of syncSelected.filter(id=>!syncDone.includes(id))){try{const result=await runAction('source.sync',id,'sources');if(result.task?.id)taskIDs=[...taskIDs,result.task.id];syncDone=[...syncDone,id];}catch(e){failures.push(errorMessage(e));}}if(failures.length)throw new Error(failures.join('；'));toast('所选外部订阅已同步');});}
 async function renameNodes(){await perform(async()=>{if(renamed.some(item=>!item.name))throw new Error('节点名称不能为空');await metadata(renamed.filter(item=>item.name!==item.row.name).map(item=>({row:item.row,patch:{name:item.name}})));renameOpen=false;});}
 const splitTags=(value:string)=>[...new Set(value.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean))];
 function toggle(id:string){selected=selected.includes(id)?selected.filter(v=>v!==id):[...selected,id];}
 function selectPage(){selected=visible.every(r=>selected.includes(r.id))?selected.filter(id=>!visible.some(r=>r.id===id)):[...new Set([...selected,...visible.map(r=>r.id)])];}
 async function perform(work:()=>Promise<void>){if(busy)return;busy=true;error='';try{await work();}catch(e){error=errorMessage(e);}finally{busy=false;}}
 async function testNodes(){await tests.run(tcpTargets.map(r=>r.id));await refreshState();}
 function startCreate(){error='';step=1;form=withManagedFields(withRealityFields({id:'',name:'',serverId:'',protocol:'VLESS',transport:'TCP / Reality',port:8443,listen:'0.0.0.0',tag:`in-${Date.now().toString(36)}`,flow:'xtls-rprx-vision',sniffing:'仅路由',status:'启用'}));createOpen=true;}
 async function next(){await perform(async()=>{if(!form.serverId||!form.name.trim())throw new Error('请选择服务器并填写名称');const server=demo.data.servers.find(s=>s.id===form.serverId);if(!server)throw new Error('服务器不存在');form.server=server.name;const issue=managedInboundError(form);if(issue)throw new Error(issue);form=await prepareManagedInbound(form);step=2;});}
 async function create(){await perform(async()=>{const row=await saveRow('inbounds',await prepareManagedInbound(form));form.id=row.id;const result=await runAction('inbound.config.apply',row.id,'inbounds');if(result.task?.id)taskIDs=[...taskIDs,result.task.id];createOpen=false;toast('入站已保存，配置下发结果请查看任务');});}
 async function importPreview(){await perform(async()=>{preview=await api('/api/nodes/import/preview',{method:'POST',body:JSON.stringify({content:importText,tags:splitTags(importTags)})});imported=false;});}
 async function importCommit(){await perform(async()=>{const result=await api('/api/nodes/import',{method:'POST',body:JSON.stringify({content:importText,tags:splitTags(importTags)})});preview=null;imported=true;importText='';await refreshState();toast(`已导入 ${result.count} 条节点，重复项自动跳过`);});}
 function edit(row:Row){editRow=row;name=row.name;tags=tagsOf(row).join(', ');region=row.region??'';description=row.description??'';error='';editOpen=true;}
 async function metadata(changes:{row:Row;patch:Record<string,any>}[]){if(!changes.length)return;if(changes.length>500)throw new Error('每次最多修改 500 个节点，请缩小选择范围');await api('/api/nodes/metadata',{method:'POST',body:JSON.stringify({rows:changes.map(({row,patch})=>({id:row.id,recordVersion:row.recordVersion,patch}))})});await refreshState();}
 async function saveMetadata(){await perform(async()=>{if(!editRow)return;await metadata([{row:editRow,patch:{name,tags:splitTags(tags),region,description}}]);editOpen=false;});}
 async function move(row:Row,direction:number){await perform(async()=>{const order=[...rows];const from=order.findIndex(r=>r.id===row.id),to=from+direction;if(to<0||to>=order.length)return;[order[from],order[to]]=[order[to],order[from]];await metadata(order.map((r,index)=>({row:r,patch:{sortOrder:index}})));});}
 async function remove(){await perform(async()=>{const failed:string[]=[];for(const row of [...deleteTargets]){try{const result=await api(`/api/collections/nodes/${encodeURIComponent(row.id)}`,{method:'DELETE'});if(result.task?.id)taskIDs=[...taskIDs,result.task.id];selected=selected.filter(id=>id!==row.id);deleteTargets=deleteTargets.filter(item=>item.id!==row.id);}catch(e){failed.push(`${row.name}：${errorMessage(e)}`);}}await refreshState();if(failed.length)throw new Error(failed.join('；'));deleteOpen=false;});}
 async function openConnection(row:Row,intent='view'){connectionIntent=intent;connectionNode=row;connection=null;subscriptionID='';subscriptions=[];error='';connectionOpen=true;await perform(async()=>{const result=await api('/api/temporary-subscriptions');subscriptions=result.subscriptions.filter((s:Row)=>s.nodes.some((n:Row)=>n.id===row.id));subscriptionID=subscriptions[0]?.id??'';});}
 async function readConnection(){await perform(async()=>{connection=await api(`/api/nodes/${encodeURIComponent(connectionNode!.id)}/connection?subscriptionId=${encodeURIComponent(subscriptionID)}`);if(connectionIntent==='copy')await copy(connection.uri);});}
 async function toggleRuntime(row:Row){await perform(async()=>{const collection=row.managedInbound?'inbounds':'nodes';const current=await getRow(collection,row.managedInbound?row.inboundId:row.id);current.status=['停用','禁用'].includes(current.status)?'启用':'禁用';const saved=await saveRow(collection,current);if(collection==='inbounds'){const result=await runAction('inbound.config.apply',saved.id,'inbounds');if(result.task?.id)taskIDs=[...taskIDs,result.task.id];}});}
 function openSpeedtest(){speedSelection=(chosen.length?chosen:filtered).map(row=>row.id);speedOpen=true;}
</script>
{#if admin&&tunnelOpen}<TunnelManager bind:open={tunnelOpen}/>{/if}

<div class="page-head"><div><div class="eyebrow">工作区 / 节点管理</div><h1>节点管理</h1><p>管理节点、标签与连接配置，按需同步外部订阅或测试连接。</p></div></div>
{#if taskIDs.length}<div class="status-banner"><div>操作已提交，请确认执行结果。<div class="actions">{#each taskIDs as id}<a href={`/tasks?detail=${encodeURIComponent(id)}`}>查看任务 {id.slice(0,8)}</a>{/each}</div></div><button class="button small" onclick={()=>taskIDs=[]}>收起</button></div>{/if}
{#if admin}
<section class="import-panel" aria-label="导入外部节点"><div class="import-body">
 <h2>导入节点</h2>
 <div class="protocol-list" aria-label="支持的导入协议">{#each ['VMess','VLESS','Trojan','Shadowsocks','Hysteria / 2','SOCKS5','HTTP','AnyTLS','Snell','TUIC · 仅导入','WireGuard · 仅导入'] as item}<span>{item}</span>{/each}</div>
 <label class="field">节点链接 / Clash YAML / JSON<textarea rows="6" bind:value={importText} disabled={busy} oninput={()=>{preview=null;imported=false;}} spellcheck="false" placeholder="vless://…&#10;trojan://…&#10;ss://…"></textarea></label>
 <label class="field">导入标签（逗号分隔）<input bind:value={importTags} disabled={busy} oninput={()=>{preview=null;imported=false;}} placeholder="例如：香港, 备用"/></label>
 {#if preview}<div class="import-preview" role="status">{#each preview.rows as row}<div class:error={row.error}>第 {row.line} 项 · {row.error??`${row.protocol} · ${row.name} · ${row.host}:${row.port} · ${row.duplicate?'重复，跳过':'可导入'}`}</div>{/each}</div>{/if}
 {#if imported}<p class="hint">导入完成，列表已更新。</p>{/if}
 <div class="actions"><button class="button" disabled={busy||!importText.trim()} onclick={importPreview}>解析预览</button><button class="button primary" disabled={busy||!preview?.valid||!preview?.count} onclick={importCommit}>导入 {preview?.count??0} 条</button><a class="button" href="/sources">管理外部订阅</a></div>
 </div></section>
{/if}
{#if error&&!createOpen&&!editOpen&&!deleteOpen&&!bulkOpen&&!connectionOpen&&!renameOpen&&!syncOpen&&!speedOpen}<p class="error" role="alert">{error}</p>{/if}
<section class="card node-workbench" aria-label="节点列表">
 <div class="list-heading"><div class="list-title"><h2>节点列表 <span>（{rows.length}）</span></h2><p>节点的修改与删除会影响使用它们的订阅。</p><small>编辑名称与标签 · 查看连接配置 · 复制 URI · 临时订阅 · 手动延迟测试</small></div>
 <div class="workbench-actions">
 {#if admin}<a class="button small" href={`/subscription-generator${selected.length?'?'+new URLSearchParams(selected.map(id=>['node',id])).toString():''}`}><Icon name="rss"/>生成订阅{selected.length?`（${selected.length}）`:''}</a>{/if}
  <div class="actions">{#if admin}<button class="button small" class:active={sortMode} aria-pressed={sortMode} disabled={busy} onclick={()=>sortMode=!sortMode}><Icon name="grip"/> {sortMode?'完成排序':'排序模式'}</button><button class="button small" onclick={startCreate}><Icon name="plus"/>创建受管入站</button><button class="button small" onclick={()=>tunnelOpen=true}><Icon name="network"/>Tunnel 管理</button><a class="button small" href="/servers?tab=outbounds"><Icon name="route"/>路由出站</a><button class="button small" disabled={!filtered.length||busy} onclick={openSpeedtest}><Icon name="activity"/>节点测速</button><button class="button small" disabled={busy||!(demo.data.sources??[]).length} onclick={startSync}><Icon name="refresh"/>同步外部订阅</button>{/if}<button class="button small" disabled={tests.state.running||!tcpTargets.length} onclick={testNodes}><Icon name="activity"/>{chosen.length?`TCP 测试（${tcpTargets.length}）`:'测试筛选结果 TCP'}</button></div>
  {#if admin}<div class="actions selection-actions"><button class="button small" disabled={!chosen.length||busy} onclick={()=>startRename('emoji')}>添加 Emoji（{chosen.length}）</button><button class="button small" disabled={!chosen.length||busy} onclick={()=>startRename('name')}>修改名称（{chosen.length}）</button><button class="button small" disabled={!chosen.length||busy} onclick={()=>{bulkOpen=true;bulkTags='';error='';}}>管理标签（{chosen.length}）</button><button class="button small danger" disabled={!chosen.length||busy} onclick={()=>startDelete(chosen)}>批量删除（{chosen.length}）</button><button class="button small danger" disabled={!rows.length||busy} onclick={()=>startDelete(rows)}>清空所有</button></div>{/if}
 </div></div>
 {#if tests.state.running}<div class="test-progress"><span>手动测试 {tests.state.completed}/{tests.state.total}</span><button class="button small" onclick={tests.stop}>停止测试</button></div>{/if}
 <div class="facets"><div class="facet"><span>按协议筛选</span><div class="chips" aria-label="协议筛选"><button class:active={!protocol} aria-pressed={!protocol} onclick={()=>protocol=''}>全部（{rows.length}）</button>{#each protocols as item}<button class:active={protocol===item} aria-pressed={protocol===item} onclick={()=>protocol=item}>{item}（{rows.filter(row=>nodeProtocol(row)===item).length}）</button>{/each}</div></div>
 <div class="facet"><span>按标签筛选</span><div class="chips" aria-label="标签筛选"><button class:active={!tag} aria-pressed={!tag} onclick={()=>tag=''}>全部（{rows.length}）</button>{#each allTags as item}<button class:active={tag===item} aria-pressed={tag===item} onclick={()=>tag=item}>{item}（{rows.filter(row=>tagsOf(row).includes(item)).length}）</button>{/each}</div></div></div>
 <div class="filters"><input aria-label="搜索节点" bind:value={search} placeholder="搜索名称、地址、地区…"/><select aria-label="来源筛选" bind:value={source}><option value="">全部来源</option>{#each sources as item}<option>{item}</option>{/each}</select><select aria-label="服务器筛选" bind:value={server}><option value="">全部服务器</option>{#each demo.data.servers as item}<option value={item.id}>{item.name}</option>{/each}</select><select aria-label="状态筛选" bind:value={status}><option value="">全部状态</option>{#each [...new Set(rows.map(r=>r.status).filter(Boolean))] as item}<option>{item}</option>{/each}</select></div>
 <div class="selection-summary"><span>筛选 {filtered.length} 条 · 已选 {chosen.length} 条</span>{#if chosen.length}<button onclick={()=>selected=[]}>取消选择</button>{/if}{#if sortMode}<span>使用节点旁的上下箭头调整全局顺序，修改即时保存。</span>{/if}</div>
 <div class="table-scroll"><table aria-label="节点管理列表"><thead><tr><th><input type="checkbox" aria-label="选择本页" checked={visible.length>0&&visible.every(r=>selected.includes(r.id))} onchange={selectPage}/></th><th>协议</th><th>节点名称</th><th>标签</th><th>服务器地址</th><th>配置</th><th>操作</th></tr></thead><tbody>
 {#each visible as row (row.id)}<tr class:selected={selected.includes(row.id)}>
 <td><input type="checkbox" aria-label={`选择 ${row.name}`} checked={selected.includes(row.id)} onchange={()=>toggle(row.id)}/></td><td><span class="protocol-badge">{nodeProtocol(row)}</span></td>
 <td><div class="node-cell"><div class="node-name"><CountryBadge region={row.region}/><div><strong>{row.name}</strong><small>{row.source??(row.managedInbound?'受管入站':'手动导入')}</small></div></div>
 {#if admin}<div class="row-tools">{#if sortMode}<button class="icon-button" aria-label={`上移 ${row.name}`} title="上移" disabled={busy||rows[0]?.id===row.id} onclick={()=>move(row,-1)}><Icon name="up" size={14}/></button><button class="icon-button" aria-label={`下移 ${row.name}`} title="下移" disabled={busy||rows.at(-1)?.id===row.id} onclick={()=>move(row,1)}><Icon name="down" size={14}/></button>{/if}<button class="icon-button" title="修改名称与标签" aria-label={`编辑 ${row.name}`} disabled={busy} onclick={()=>edit(row)}><Icon name="edit" size={14}/></button>{#if row.managedInbound}<a class="icon-button" title="入站配置" aria-label={`入站配置 ${row.name}`} href={inboundManagerURL(row)}><Icon name="code" size={14}/></a>{/if}{#if routingURL('nodes',row)}<a class="icon-button" title="路由规则" aria-label={`路由规则 ${row.name}`} href={routingURL('nodes',row)}><Icon name="route" size={14}/></a>{/if}</div>{/if}</div></td>
 <td><div class="tags">{#each tagsOf(row) as t}<button class="tag" onclick={()=>tag=t}>{t}</button>{:else}<span class="muted">—</span>{/each}</div></td>
 <td><span class="address">{nodeRelay(row,demo.data.relays??[])?.relayAddress??nodeAddress(row)}</span>{#if nodeRelay(row,demo.data.relays??[])}<small class="muted">原服务器：{nodeAddress(row)}</small>{/if}<div class="connection-state"><Badge value={row.status??'启用'}/><small title={tests.state.results[row.id]?.error??row.latencyError??'主控到节点的 TCP 连接延迟'}>{#if tests.state.results[row.id]?.status==='success'}{tests.state.results[row.id].latency} ms{:else if tests.state.results[row.id]?.status==='failed'}测试失败{:else if ['running','queued'].includes(tests.state.results[row.id]?.status??'')}测试中…{:else}{row.latency!=null?`${row.latency} ms`:'未测试'}{/if}</small></div></td>
 <td><div class="row-tools"><button class="icon-button" title={canTestNode('admin',row)?'TCP 延迟测试':'UDP 节点请使用节点测速中的延迟测试'} aria-label={`测试 ${row.name}`} disabled={tests.state.running||!canTestNode(demo.user?.role,row)} onclick={()=>tests.run([row.id])}><Icon name="activity" size={15}/></button><button class="icon-button" title="查看连接配置" aria-label={`查看配置 ${row.name}`} disabled={busy} onclick={()=>openConnection(row)}><Icon name="eye" size={15}/></button><button class="icon-button" title="生成并复制 URI" aria-label={`复制 URI ${row.name}`} disabled={busy} onclick={()=>openConnection(row,'copy')}><Icon name="copy" size={15}/></button><a class="icon-button" title="生成临时订阅" aria-label={`临时订阅 ${row.name}`} href={`/temporary-subscriptions?node=${encodeURIComponent(row.id)}`}><Icon name="link" size={15}/></a></div></td>
 <td>{#if admin}<div class="row-tools"><button class="icon-button" title={['禁用','停用'].includes(row.status)?'启用':'停用'} aria-label={`切换状态 ${row.name}`} disabled={busy} onclick={()=>toggleRuntime(row)}><Icon name={['禁用','停用'].includes(row.status)?'play':'pause'} size={14}/></button><button class="icon-button danger" title="删除节点" aria-label={`删除 ${row.name}`} disabled={busy} onclick={()=>startDelete([row])}><Icon name="x" size={15}/></button></div>{:else}<span class="muted">—</span>{/if}</td>
 </tr>{:else}<tr><td colspan="7"><div class="empty">没有符合条件的节点</div></td></tr>{/each}</tbody></table></div>
 <div class="table-footer"><span>第 {Math.floor(offset/20)+1} 页 · 共 {filtered.length} 条</span><div class="actions"><button class="button small" disabled={offset===0} onclick={()=>offset=Math.max(0,offset-20)}>上一页</button><button class="button small" disabled={offset+20>=filtered.length} onclick={()=>offset+=20}>下一页</button></div></div>
</section>

<Modal bind:open={createOpen} title={step===1?'新增受管节点':'确认节点配置'} wide>
 {#if step===1}<div class="form-grid"><label class="field">名称<input bind:value={form.name}/></label><label class="field">服务器<select bind:value={form.serverId}><option value="">请选择</option>{#each demo.data.servers as s}<option value={s.id}>{s.name} · {s.status} · {s.address}</option>{/each}</select></label><label class="field">监听端口<input type="number" min="1" max="65535" bind:value={form.port}/></label><label class="field">监听地址<input bind:value={form.listen}/></label><label class="field">入站标识<input bind:value={form.tag}/></label></div><ManagedProtocolFields bind:form server={demo.data.servers.find(s=>s.id===form.serverId)} bind:busy={keyBusy}/>{:else}<p class="hint">服务器：{form.server} · {form.listen}:{form.port} · {form.protocol} / {form.transport}</p><pre class="config-preview">{JSON.stringify({...form,privateKey:form.privateKey?'••••••':undefined},null,2)}</pre>{/if}
 {#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button class="button" onclick={()=>createOpen=false}>取消</button>{#if step===2}<button class="button" onclick={()=>step=1}>上一步</button><button class="button primary" disabled={busy} onclick={create}>保存并下发</button>{:else}<button class="button primary" disabled={busy||keyBusy} onclick={next}>预览配置</button>{/if}</div>
</Modal>
<Modal bind:open={editOpen} title="节点显示信息"><div class="form-grid"><label class="field">名称<input bind:value={name}/></label><label class="field">地区 / 国家代码<input bind:value={region}/></label><label class="field">标签<input bind:value={tags}/></label><label class="field">描述<input bind:value={description}/></label></div>{#if editRow?.managedInbound}<p class="hint">连接参数和启停状态由关联入站管理。此处显示信息在同步后保留。</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button class="button" onclick={()=>editOpen=false}>取消</button><button class="button primary" disabled={busy} onclick={saveMetadata}>保存</button></div></Modal>
<Modal bind:open={bulkOpen} title={`修改 ${chosen.length} 个节点的标签`} description="替换所选节点的标签；留空将清除标签。"><label class="field">标签<input bind:value={bulkTags}/></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button class="button" onclick={()=>bulkOpen=false}>取消</button><button class="button primary" disabled={busy} onclick={()=>perform(async()=>{await metadata(chosen.map(row=>({row,patch:{tags:splitTags(bulkTags)}})));bulkOpen=false;})}>保存</button></div></Modal>
<Modal bind:open={deleteOpen} title={`删除 ${deleteTargets.length} 个节点`} description="受管节点会同时删除关联入站并下发配置。已有套餐不会自动扩大节点范围。"><div class="import-preview">{#each deleteTargets as row}<div>{row.name} · {row.managedInbound?'删除节点及入站':'删除节点记录'}</div>{/each}</div>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button class="button" disabled={busy} onclick={()=>deleteOpen=false}>取消</button><button class="button danger" disabled={busy} onclick={remove}>确认删除</button></div></Modal>
<Modal bind:open={connectionOpen} title={`${connectionNode?.name??'节点'} · 连接配置`} description="使用你本人有效套餐实例的连接凭据。" wide>{#if subscriptions.length}<label class="field">套餐实例<select bind:value={subscriptionID} onchange={()=>connection=null}>{#each subscriptions as s}<option value={s.id}>{s.name??s.plan}</option>{/each}</select></label><button class="button space-top" disabled={busy||!subscriptionID} onclick={readConnection}>{connectionIntent==='copy'?'生成并复制 URI':'生成连接配置'}</button>{:else}<p class="hint">当前账户没有可使用此节点的套餐。请先分配套餐或前往成员账户查看。</p>{/if}{#if connection}<label class="field space-top">URI<textarea readonly value={connection.uri}></textarea></label><button class="button small" onclick={()=>copy(connection.uri)}>复制 URI</button><pre class="config-preview">{JSON.stringify(connection.clash,null,2)}</pre><button class="button small" onclick={()=>copy(JSON.stringify(connection.clash,null,2))}>复制 Clash 节点配置</button>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button class="button" onclick={()=>connectionOpen=false}>关闭</button></div></Modal>

{#if admin&&speedOpen}<NodeSpeedtest bind:open={speedOpen} initialSelection={speedSelection}/>{/if}
<Modal bind:open={renameOpen} title={renameMode==='emoji'?`为 ${batchRows.length} 个节点添加 Emoji`:`修改 ${batchRows.length} 个节点名称`} description={renameMode==='emoji'?'根据节点已有地区添加国旗；地区未知的节点保持原名。':'先预览修改结果，再统一保存。替换内容按普通文字匹配。'} wide>
 {#if renameMode==='name'}<div class="form-grid"><label class="field">名称前缀<input bind:value={renamePrefix}/></label><label class="field">名称后缀<input bind:value={renameSuffix}/></label><label class="field">查找文字<input bind:value={renameFind}/></label><label class="field">替换为<input bind:value={renameReplacement}/></label></div>{/if}
 <div class="import-preview">{#each renamed as item}<div>{item.row.name} → <strong>{item.name||'（名称为空）'}</strong></div>{/each}</div>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button class="button" disabled={busy} onclick={()=>renameOpen=false}>取消</button><button class="button primary" disabled={busy||!renamed.length||renamed.some(item=>!item.name)||renamed.every(item=>item.name===item.row.name)} onclick={renameNodes}>保存名称</button></div>
</Modal>
<Modal bind:open={syncOpen} title="同步外部订阅" description="选择需要手动同步的来源。同步将请求来源地址，并按来源设置更新节点。">
 <div class="source-choices">{#each demo.data.sources??[] as item}<label><input type="checkbox" value={item.id} bind:group={syncSelected} disabled={busy||syncDone.includes(item.id)}/>{item.name}{syncDone.includes(item.id)?' · 已同步':''}</label>{:else}<p class="hint">尚无外部订阅。</p>{/each}</div><a href="/sources">管理外部订阅来源</a>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button class="button" disabled={busy} onclick={()=>syncOpen=false}>关闭</button><button class="button primary" disabled={busy||!syncSelected.some(id=>!syncDone.includes(id))} onclick={syncSources}>同步所选来源</button></div>
</Modal>
