 .import-panel{border-bottom:1px solid var(--line);padding-bottom:20px}.import-panel h2{font-size:16px;margin:0}.protocol-list{display:flex;flex-wrap:wrap;gap:6px 16px;color:var(--muted);font-size:12px}.protocol-list span{white-space:nowrap}.import-panel .import-body{padding:0;display:grid;gap:14px}.import-panel textarea{min-height:150px;resize:vertical}.import-panel .import-preview{border-radius:6px}
 .import-panel{margin-bottom:16px}.import-body{padding:0 20px 20px;display:grid;gap:12px}.import-body textarea{font-family:monospace}.list-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;padding:20px 20px 16px}.list-title{flex:1;min-width:230px}.list-title h2{font-size:16px}.list-title h2 span{font-weight:400}.list-title p{font-size:12px;color:var(--danger);margin:6px 0}.list-title small{color:var(--muted);font-size:11px;line-height:1.8}.workbench-actions{flex:2;min-width:0;display:grid;gap:7px}.workbench-actions .actions{justify-content:flex-end;gap:6px}.selection-actions .button{border-color:color-mix(in srgb,var(--primary) 35%,var(--line))}.facets{padding:0 20px;display:grid;gap:12px}.facet>span{display:block;font-size:12px;margin-bottom:7px}.chips{display:flex;gap:6px;flex-wrap:wrap}.chips button{padding:7px 12px;border:1px solid var(--line);border-radius:5px;background:var(--nested);color:var(--muted);font-size:12px;overflow-wrap:anywhere;max-width:100%}.chips button.active,.button.active{background:var(--primary);border-color:var(--primary);color:white}.selection-summary,.test-progress{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:0 20px 12px;font-size:11px;color:var(--muted)}.selection-summary button{border:0;background:none;color:var(--primary);padding:0}.node-workbench table{min-width:1040px;width:100%;font-size:12px}.node-workbench th{white-space:nowrap}.node-workbench td,.node-workbench th{padding:13px 12px}.node-workbench tr.selected{background:color-mix(in srgb,var(--primary) 10%,transparent)}.node-cell{display:flex;align-items:center;justify-content:space-between;gap:20px}.node-cell strong{font-size:12px;overflow-wrap:anywhere}.row-tools{display:flex;align-items:center;gap:5px;white-space:nowrap}.row-tools .icon-button{width:28px;height:28px;min-width:28px;border:1px solid var(--line);border-radius:4px;color:var(--primary)}.row-tools .danger{color:var(--danger)}.protocol-badge{font-size:10px;border:1px solid color-mix(in srgb,var(--primary) 30%,var(--line));background:color-mix(in srgb,var(--primary) 10%,transparent);color:var(--primary);padding:3px 6px;border-radius:3px}.connection-state{display:flex;align-items:center;gap:8px;margin-top:6px}.connection-state small{color:var(--muted);font-size:10px}.source-choices{display:grid;gap:10px;margin:16px 0}.source-choices label{display:flex;align-items:center;gap:8px}.source-choices input{width:15px;min-height:15px}.tags .tag{max-width:200px;overflow-wrap:anywhere;white-space:normal}.node-workbench .table-scroll{margin:0 20px;border:1px solid var(--line);overflow:auto}.node-workbench{min-width:0}@media(max-width:1000px){.list-heading{flex-direction:column;gap:12px}.workbench-actions{width:100%}.workbench-actions .actions{justify-content:flex-start}}@media(max-width:600px){.list-heading,.facets{padding-left:12px;padding-right:12px}.node-workbench .table-scroll{margin:0 12px}.import-body{padding:0 12px 14px}.list-title{min-width:0}.table-footer{gap:10px;flex-wrap:wrap}}
 .filters{display:flex;gap:10px;padding:18px;flex-wrap:wrap}.filters input{flex:2;min-width:200px}.filters select{flex:1;min-width:125px}.node-name{display:flex;align-items:center;gap:10px;min-width:180px}.node-name small{display:block;color:var(--muted);margin-top:4px}td{vertical-align:middle}.tags{display:flex;gap:4px;flex-wrap:wrap;margin-top:5px}.tag{font-size:11px}.address{font-family:monospace;white-space:nowrap}.actions{flex-wrap:wrap}.config-preview{max-height:340px;overflow:auto;background:var(--bg);padding:16px;border-radius:10px;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;margin-top:16px}.import-preview{max-height:260px;overflow:auto;padding:12px;border:1px solid var(--line);border-radius:10px;margin-top:12px;line-height:1.9}.node-workbench{overflow:visible}.table-scroll{min-height:230px}.table-footer{display:flex;justify-content:space-between;align-items:center;padding:16px}.status-banner{margin-bottom:16px}
